# SPDX-License-Identifier: MIT

import pytest

import attrs


@pytest.mark.parametrize("slots", [False, True])
@pytest.mark.parametrize("result_type", [list, tuple, iter])
def test_transformer_iterable_subclass(slots, result_type):
    """Transformed fields survive validation and remain inheritable."""

    def after_first_kw_only(cls, fields):
        return result_type(
            field if i == 0 else field.evolve(kw_only=True)
            for i, field in enumerate(fields)
        )

    @attrs.define(slots=slots, field_transformer=after_first_kw_only)
    class Base:
        dag_id: str
        has_default: str = "default"

    @attrs.define(slots=slots)
    class Subclass(Base):
        other: bool

    assert attrs.asdict(Base(dag_id="foo")) == {
        "dag_id": "foo",
        "has_default": "default",
    }
    instance = Subclass(dag_id="foo", other=False)
    assert attrs.asdict(instance) == {
        "dag_id": "foo",
        "has_default": "default",
        "other": False,
    }
    assert instance == Subclass("foo", False)
    assert instance.has_default == "default"


def test_generator_transformer_resolves_alias():
    """Alias resolution also traverses a generator's transformed fields."""

    @attrs.define(field_transformer=lambda cls, fields: (f for f in fields))
    class C:
        _value: int

    assert C(value=42)._value == 42
    assert attrs.fields(C)._value.alias == "value"
EOF
