import pytest

import attrs


@pytest.mark.parametrize("slots", [False, True])
def test_generator_transformer_inheritance(slots):
    """Generator results retain fields, keyword-only flags, and aliases."""
    def transform(cls, fields):
        fields = iter(fields)
        yield next(fields)
        for field in fields:
            yield field.evolve(kw_only=True)

    @attrs.define(slots=slots, field_transformer=transform)
    class Base:
        dag_id: str
        _has_default: str = "default"

    @attrs.define(slots=slots)
    class Subclass(Base):
        other: bool

    instance = Subclass(dag_id="foo", other=False)
    assert attrs.asdict(instance) == {
        "dag_id": "foo", "_has_default": "default", "other": False
    }
    assert Subclass("foo", False, has_default="custom")._has_default == "custom"
    assert [field.name for field in attrs.fields(Base)] == [
        "dag_id", "_has_default"
    ]
EOF
